import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Employee } from './employee.entity';
import { EmployeeRepository } from './employee.repository';

@Injectable()
export class EmployeeService {
  constructor(
    @InjectRepository(Employee)
    private employeeRepository: EmployeeRepository,
  ) {}

  async getAll(): Promise<Employee[]> {
    return this.employeeRepository.find();
  }

  async getOne(id: string): Promise<Employee> {
    const employee = await this.employeeRepository.findOne({ where: { id } });
    return employee;
  }

  async create(employee: Employee): Promise<Employee> {
    const employeeRepository = this.employeeRepository;
    const employeeAlreadyExists = await employeeRepository.findOne({ where: { id: employee.id } });
    if (employeeAlreadyExists) {
      throw new Error('Employee already exists');
    }
    employeeRepository.create(employee);
    return employee;
  }

  async update(id: string, employee: Employee): Promise<Employee> {
    const employeeRepository = this.employeeRepository;
    const employeeExists = await employeeRepository.findOne({ where: { id } });
    if (!employeeExists) {
      throw new Error('Employee not found');
    }
    employeeRepository.update(id, employee);
    return employee;
  }

  async delete(id: string): Promise<void> {
    const employeeRepository = this.employeeRepository;
    const employeeExists = await employeeRepository.findOne({ where: { id } });
    if (!employeeExists) {
      throw new Error('Employee not found');
    }
    employeeRepository.delete(id);
  }
}
```

